(()=>{'use strict';
const M=window.ConnextModel,C=window.CONNEXT_CONFIG;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',alert:'m12 3 10 18H2L12 3z M12 9v5 M12 17h.01',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z',arrows:'M4 7h15l-4-4 M19 7l-4 4 M20 17H5l4-4 M5 17l4 4',building:'M4 21V4h11v17 M15 9h5v12 M2 21h20 M7 8h1 M11 8h1 M7 12h1 M11 12h1 M7 16h1 M11 16h1',chart:'M3 3v18h18 M7 15v-4 M12 15V7 M17 15v-7',book:'M12 5C9 3 5 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1z M12 5v15',search:'m21 21-4.3-4.3 M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',check:'m5 12 4 4L19 6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3z M20 2v4 M18 4h4',shield:'M12 3 3 7v5c0 6 9 10 9 10s9-4 9-10V7l-9-4z m-4 9 3 3 5-6',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',wallet:'M3 6h17v14H3z M3 6V3h14v3 M15 11h6v5h-6z',home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-8h6v8',award:'M16 8a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M7 12 5 21l7-3 7 3-2-9',access:'M14 4a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M3 9h18 M12 9v5 M8 22l4-8 4 8',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',monitor:'M2 3h20v14H2z M8 21h8 M12 17v4',refresh:'M20 7v5h-5 M4 17v-5h5 M19 6a8 8 0 0 0-14 2 M5 18a8 8 0 0 0 14-2',menu:'M3 6h18 M3 12h18 M3 18h18',close:'m6 6 12 12 M18 6 6 18',calendar:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M7 14h2 M13 14h2',pause:'M8 4v16 M16 4v16',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0 M14 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',note:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5',mic:'M9 3h6v11H9z M5 10v3a7 7 0 0 0 14 0v-3 M12 20v2',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.folder}"/></svg>`;
let role=sessionStorage.getItem('connext-role')||'coordinator',data,route,viewTab='overview',queueTab='all',q='',deptFilter='',priorityFilter='',sort='priority',intakeDraft=null,chat=[];
const dept=id=>data.departments.find(d=>d.id===id)||{name:id,short:id,color:'#8a9a80',icon:'folder'};
const student=id=>data.students.find(s=>s.id===id);
const user=()=>data.roles.find(r=>r.id===role)||data.roles[0];
const date=(s,options={day:'numeric',month:'short'})=>new Date(s).toLocaleDateString('en-IN',options);
const relative=s=>M.days(s)===0?'Today':`${M.days(s)} days ago`;
const badge=(text,type)=>`<span class="tag ${type||({Urgent:'urgent',High:'high',Moderate:'medium','On track':'success',Pending:'high',Accepted:'success','In progress':'blue',Resolved:'success','Waiting on student':'neutral'}[text]||'neutral')}">${esc(text)}</span>`;
const avatar=(s,large=false)=>`<span class="avatar ${large?'lg':''}" style="background:${s.color||'#e6eddf'}">${esc(s.initials)}</span>`;
const btn=(text,action,cls='',attrs='',ic)=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${text}</button>`;
const deptOptions=(selected='',includeAll=false)=>`${includeAll?'<option value="">All departments</option>':''}${data.departments.map(d=>`<option value="${d.id}" ${d.id===selected?'selected':''}>${esc(d.name)}</option>`).join('')}`;
const studentOptions=id=>data.students.map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${esc(s.name)} · ${s.roll}</option>`).join('');
const activeCases=()=>data.cases.filter(c=>c.status!=='Resolved');
const queue=()=>data.students.map(s=>({...s,...M.flags(s,data)})).sort((a,b)=>b.score-a.score||b.wait-a.wait||a.name.localeCompare(b.name));
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function go(path){if(location.hash===`#${path}`)render();else location.hash=path;}
function mutate(action,payload,message){try{M.mutate(action,payload,role);if(message)toast(message);return true;}catch(e){toast(e.message);return false;}}
function heading(title,subtitle,actions='',eyebrow='STUDENT SUPPORT WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function shell(content){const flagged=queue().filter(s=>s.score>0).length;const nav=[['overview','grid','Overview'],['attention','alert','Needs attention',flagged],['students','users','Students'],['cases','folder','All cases'],['handoffs','arrows','Handoffs',data.handoffs.filter(h=>h.status==='Pending').length],['departments','building','Departments'],['insights','chart','Insights'],['knowledge','book','Knowledge base']];const current=route.split('/')[0];return `<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#home" aria-label="Connext home"><span class="brand-mark"></span>connext<span style="color:var(--lime)">.</span></a><div class="workspace-label">Workspace</div><nav class="nav" aria-label="Main navigation">${(role==='student'?[['student','users','My support']]:nav).map(([id,ic,label,count])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(ic)}${label}${count?`<span class="nav-count">${count}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="overline">One student. One story.</span><p>Connected support.<br>Across every department.</p></div><div class="brand-footer"><strong>IGDTUW</strong><span style="opacity:.4">×</span><span class="servicenow">service<span>now</span></span></div><div class="event-footer">TEAM 9 &nbsp; / &nbsp; CO-INNOVATION DAY</div></div></aside><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumbs">Workspace ${icon('chevron')} <strong>${esc(current==='profile'?'Student 360':nav.find(n=>n[0]===current)?.[2]||'My support')}</strong></div><div class="topbar-spacer"></div><form class="global-search" id="global-search">${icon('search')}<input name="query" aria-label="Search all students" placeholder="Search anything..."><span class="keycap">/</span></form><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}<span class="notification-dot"></span></button><div class="profile-control">${avatar(user())}<div><div class="profile-name">${esc(user().user)}</div><select class="role-picker" id="role" aria-label="Demo role switcher">${data.roles.map(r=>`<option value="${r.id}" ${r.id===role?'selected':''}>${r.short}</option>`).join('')}</select></div></div></header><main class="main" id="main">${content}<footer class="page-footer"><span>Connext · IGDTUW × ServiceNow &nbsp; / &nbsp; Joined-up student support</span><span class="sync">Demo changes saved on this device</span></footer></main></div>`;}
function notice(){return `<div class="demo-notice"><span class="demo-pill">Demo workspace</span> All students and records are fictional. AI and sign-in are simulated.<a href="#" data-action="about">About this demo</a><button class="text-link" data-action="reset" style="font-size:11px;white-space:nowrap">${icon('refresh')} Reset demo</button></div>`;}
function metrics(){const students=queue(),waiting=data.handoffs.filter(h=>h.status==='Pending'),urgent=students.filter(s=>['Urgent','High'].includes(s.level));const items=[['Active cases',activeCases().length,'folder',`${data.students.length} students across ${new Set(activeCases().map(c=>c.department)).size} departments`,'Connected in one place'],['Need attention',students.filter(s=>s.score>0).length,'alert',`${urgent.length} need a priority response`,'Review the connected signals'],['Pending handoffs',waiting.length,'arrows',`${waiting.filter(h=>M.days(h.createdAt)>C.referralDays).length} waiting over ${C.referralDays} days`,'Keep support moving'],['Multi-department',students.filter(s=>s.departments.length>=C.departmentCount).length,'users',`${C.departmentCount}+ departments per student`,'A single, shared story']];return `<div class="metrics">${items.map(([label,value,ic,sub,bottom])=>`<div class="metric"><div class="metric-top">${label}${icon(ic)}</div><div class="metric-value">${value}</div><div class="metric-bottom"><span class="${label==='Need attention'||label==='Pending handoffs'?'warning':'positive'}">${sub}</span></div><div class="metric-bottom" style="margin-top:5px">${bottom}</div></div>`).join('')}</div>`;}
function deptStack(ids){return `<div class="dept-stack" aria-label="${esc(ids.map(id=>dept(id).short).join(', '))}">${ids.slice(0,3).map(id=>`<span class="dept-dot" style="background:${dept(id).color}" title="${esc(dept(id).name)}">${dept(id).short.slice(0,2).toUpperCase()}</span>`).join('')}${ids.length>3?`<span class="dept-dot dept-more">+${ids.length-3}</span>`:''}${ids.length===0?'<span class="small-meta">No active cases</span>':''}</div>`;}
function queueRows(limit=0){let rows=queue().filter(s=>s.score>0);if(queueTab==='mine'&&role!=='coordinator')rows=rows.filter(s=>s.departments.includes(user().department));if(queueTab==='urgent')rows=rows.filter(s=>s.level==='Urgent'||s.level==='High');rows=rows.filter(s=>(`${s.name} ${s.roll} ${s.course}`.toLowerCase().includes(q.toLowerCase()))&&(!deptFilter||s.departments.includes(deptFilter))&&(!priorityFilter||s.level===priorityFilter));if(sort==='wait')rows.sort((a,b)=>b.wait-a.wait);if(sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));const total=rows.length;if(limit)rows=rows.slice(0,limit);return {total,html:rows.map(s=>`<tr class="queue-row ${s.id==='aanya'?'hero':''}" data-action="profile" data-id="${s.id}" tabindex="0"><td><div class="person">${avatar(s)}<div><div class="person-name">${esc(s.name)}</div><div class="person-meta">Year ${s.year} · ${s.course==='Computer Science'?'CSE':s.course==='Information Technology'?'IT':s.course==='Electronics'?'ECE':s.course==='Architecture'?'Architecture':'MAE'}</div></div></div></td><td>${badge(s.level)}<div class="reason">${esc(s.flags[0]?.label||'On track')}${s.flags.length>1?` <span title="${esc(s.flags.slice(1).map(f=>f.reason).join(' '))}">+${s.flags.length-1}</span>`:''}</div></td><td>${deptStack(s.departments)}</td><td><span class="wait-time">${s.wait} days</span></td><td><button class="icon-button row-arrow" data-action="profile" data-id="${s.id}" aria-label="Open ${esc(s.name)}">${icon('arrow')}</button></td></tr>`).join('')||`<tr><td colspan="5"><div class="empty">${icon('check')}No students match these filters.</div></td></tr>`};}
function queueCard(full=false){const rows=queueRows(full?0:5);return `<section class="card"><div class="card-head"><div><div class="card-title"><h2>Needs attention</h2><span class="count">${queue().filter(s=>s.score>0).length} students</span></div><p class="card-description">Small signals. A more connected picture.</p></div>${!full?'<a class="text-link" href="#attention">View all '+icon('arrow')+'</a>':''}</div><div class="tabs" aria-label="Queue filters"><button data-action="queueTab" data-tab="all" class="${queueTab==='all'?'active':''}">All flagged</button><button data-action="queueTab" data-tab="urgent" class="${queueTab==='urgent'?'active':''}">High priority</button><button data-action="queueTab" data-tab="mine" class="${queueTab==='mine'?'active':''}">My department</button></div><div class="filters" style="padding-top:15px"><label class="search-box">${icon('search')}<input id="queue-search" aria-label="Search attention queue" placeholder="Search students..." value="${esc(q)}"></label><select id="department-filter" class="filter-select" aria-label="Filter by department">${deptOptions(deptFilter,true)}</select>${full?`<select id="priority-filter" class="filter-select" aria-label="Filter by priority"><option value="">All priorities</option>${['Urgent','High','Moderate'].map(p=>`<option ${p===priorityFilter?'selected':''}>${p}</option>`).join('')}</select>`:''}<select id="queue-sort" class="filter-select" aria-label="Sort attention queue"><option value="priority" ${sort==='priority'?'selected':''}>Priority first</option><option value="wait" ${sort==='wait'?'selected':''}>Longest wait</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option></select></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Attention level</th><th>Departments</th><th>Waiting</th><th></th></tr></thead><tbody id="queue-body">${rows.html}</tbody></table></div><div class="card-footer"><span id="queue-count">Showing ${Math.min(full?rows.total:5,rows.total)} of ${rows.total} flagged students</span><span>Ranked by support urgency</span></div></section>`;}
function workload(){const list=data.departments.map(d=>({...d,count:activeCases().filter(c=>c.department===d.id).length})).filter(d=>d.count).sort((a,b)=>b.count-a.count).slice(0,5);return `<section class="card"><div class="card-head"><h2>Across departments</h2>${icon('building')}</div><div class="workload">${list.map(d=>`<div class="workload-item"><div class="workload-label"><span>${d.short}</span><span>${d.count} open</span></div><div class="bar-track"><div class="bar-fill" style="width:${d.count/Math.max(...list.map(x=>x.count))*100}%;background:${d.color}88"></div></div></div>`).join('')}</div><div class="card-footer"><a href="#departments" class="text-link">Explore all 12 departments ${icon('arrow')}</a></div></section>`;}
function activityList(limit=3){return [...data.events].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,limit).map(e=>`<div class="activity"><div class="activity-icon">${icon(e.type==='handoff'?'arrows':e.type==='task'?'check':'note')}</div><div class="activity-text"><strong>${esc(student(e.studentId)?.name.split(' ')[0])}</strong> · ${esc(e.text)}<small>${esc(dept(e.department).short)} &nbsp; · &nbsp; ${relative(e.at)}</small></div></div>`).join('');}
function overview(){return heading(`A clearer picture. Better support.`,`Here’s what needs your attention today, ${esc(user().user.replace('Dr. ','').split(' ')[0])}.`,btn('Daily briefing','briefing','','', 'spark')+btn('New case','intake','primary','','plus'))+notice()+metrics()+`<div class="overview-grid">${queueCard()}<aside class="side-stack"><section class="brief-card"><div class="brief-label">${icon('spark')} CONNEXT INTELLIGENCE</div><h2>See the story<br>between the signals.</h2><p>${queue().filter(s=>s.departments.length>=3).length} students are working with three or more departments. A shared brief helps everyone take the right next step.</p>${btn('Prepare my daily briefing','briefing','','','arrow')}<div class="brief-bottom">${icon('shield')} Role-aware · Simulated AI</div></section>${workload()}</aside></div><div class="overview-bottom"><section class="card"><div class="card-head"><h2>Latest activity</h2><span class="small-meta">Shared across teams</span></div><div class="activity-list">${activityList()}</div></section><section class="card"><div class="card-head"><h2>Handoffs to follow up</h2><a class="text-link" href="#handoffs">View all ${icon('arrow')}</a></div>${data.handoffs.filter(h=>h.status==='Pending').slice(0,2).map(h=>`<div class="handoff-mini"><div><div class="person-name">${esc(student(h.studentId)?.name)}</div><div class="handoff-route">${dept(h.from).short} → ${dept(h.to).short}</div></div>${badge(`${M.days(h.createdAt)} days waiting`,'high')}</div>`).join('')||'<div class="empty">All handoffs have been accepted.</div>'}</section></div>`;}
function render(){data=M.get(role);route=(location.hash.slice(1)||'overview');if(role==='student'&&route!=='home')route='student';document.title=`Connext · ${route.startsWith('profile/')?student(route.split('/')[1])?.name||'Student':route.charAt(0).toUpperCase()+route.slice(1)}`;let content;try{content=route==='overview'?overview():route==='attention'?heading('A little attention goes a long way.','A shared queue of students who may need a coordinated response.',btn('New case','intake','primary','','plus'))+notice()+queueCard(true):renderOther();}catch(e){console.error(e);content='<div class="empty">This view could not be loaded. <a href="#overview">Return to overview</a></div>';}$('#app').innerHTML=route==='home'?content:shell(content);}
function homePage(){
 const workspace=role==='student'?'student':'overview';
 const workspaceLabel=role==='student'?'View my support':'Open workspace';
 const features=role==='student'?
  [['folder','Your support, together','See the status of your requests in one place.'],['arrows','Context moves with you','Teams coordinate the next step without making you start over.'],['shield','Thoughtful information sharing','Sensitive notes stay within the authorised team’s view.']]:
  [['users','See the whole student','Bring department cases, next steps and the shared timeline into one view.','students','Explore students'],['alert','Notice the missing connection','Spot delayed referrals and signals that only make sense together.','attention','Review the queue'],['arrows','Pass on more than a case','Send a context brief and track ownership until the next team accepts.','handoffs','View handoffs']];
 return `<div class="home-page">
  <header class="home-header"><a class="brand" href="#home" aria-label="Connext home"><span class="brand-mark"></span>connext<span class="home-brand-dot">.</span></a><nav class="home-nav" aria-label="Home navigation"><a href="#home" aria-current="page">Home</a>${role!=='student'?'<a href="#departments">Departments</a>':''}<button data-action="about">About the demo</button></nav><a class="btn primary home-header-cta" href="#${workspace}">${workspaceLabel} ${icon('arrow')}</a></header>
  <main id="main">
   <section class="home-hero" aria-labelledby="home-title"><div class="home-hero-inner">
    <div class="home-intro"><div class="home-eyebrow">IGDTUW × SERVICENOW &nbsp; / &nbsp; JOINED-UP STUDENT SUPPORT</div><h1 id="home-title">Support that sees<br>the <span>whole student.</span></h1><p>One student shouldn’t have to tell their story twelve times. Connect the people, context and next steps that turn separate requests into shared support.</p><div class="home-actions"><a class="btn lime" href="#${workspace}">${workspaceLabel} ${icon('arrow')}</a>${role!=='student'?'<a class="home-secondary" href="#students">Meet the demo students '+icon('users')+'</a>':''}</div><div class="home-session">${avatar(user())}<span>Continue as <strong>${esc(user().user)}</strong><small>${esc(user().name)} · Demo account</small></span></div></div>
    <div class="home-journey" aria-label="How connected student support works"><div class="home-journey-heading"><span>${icon('arrows')} THE CONNECTED JOURNEY</span>${badge('One shared story','success')}</div><div class="home-journey-step"><span class="home-step-number">01</span><div><h2>A student reaches out</h2><p>“I need help with my fees and missed classes.”</p></div></div><div class="home-journey-connector"></div><div class="home-journey-step"><span class="home-step-number">02</span><div><h2>The right teams come together</h2><p>Shared context. Clear departmental ownership.</p><div class="home-department-tags">${['fees','academics','affairs'].map(id=>`<span>${icon(dept(id).icon)}${dept(id).short}</span>`).join('')}</div></div></div><div class="home-journey-connector"></div><div class="home-journey-step"><span class="home-step-number">03</span><div><h2>Support moves forward</h2><p>A warm handoff, a clear next step, and one shared timeline.</p></div></div><div class="home-journey-footer">${icon('shield')} Sensitive details stay in authorised views.</div></div>
   </div><div class="home-principles"><div><strong>12</strong><span>departments, connected</span></div><div><strong>1</strong><span>shared student journey</span></div><div>${icon('heart')}<span>People at the centre<br>of every next step</span></div></div></section>
   <section class="home-features" aria-labelledby="home-features-title"><div class="home-section-heading"><div><div class="eyebrow">LESS FRAGMENTATION. MORE UNDERSTANDING.</div><h2 id="home-features-title">Good support starts with connection.</h2></div><p>The context to understand.<br>The tools to follow through.</p></div><div class="home-feature-grid">${features.map(([ic,title,description,target,label])=>`<article class="home-feature"><div class="home-feature-icon">${icon(ic)}</div><h3>${title}</h3><p>${description}</p>${target?`<a href="#${target}">${label} ${icon('arrow')}</a>`:''}</article>`).join('')}</div></section>
  </main><footer class="home-footer"><div><strong>IGDTUW</strong><span>×</span><span class="servicenow">service<span>now</span></span><small>Team 9 · Co-Innovation Day</small></div><p>Fictional data · Simulated AI and sign-in · Built for demonstration.</p></footer>
 </div>`;
}
function renderOther(){
 if(route==='home')return homePage();
 if(route==='students')return studentsPage();
 if(route.startsWith('profile/'))return profilePage(route.split('/')[1]);
 if(route==='cases')return casesPage();
 if(route==='handoffs')return handoffsPage();
 if(route==='departments'||route.startsWith('departments/'))return departmentsPage(route.split('/')[1]);
 if(route==='insights')return insightsPage();
 if(route==='knowledge')return knowledgePage();
 if(route==='student')return studentPage();
 return heading('Page not found','This workspace could not be found.')+'<a class="btn" href="#overview">Back to overview</a>';
}
function studentsPage(){return heading('Every student. One connected story.','Find a student and see how their support fits together.',btn('New case','intake','primary','','plus'))+notice()+`<div class="filters" style="padding:0 0 22px"><label class="search-box">${icon('search')}<input id="student-search" value="${esc(q)}" placeholder="Search by name, demo ID or programme" aria-label="Search student directory"></label><select id="student-year" class="filter-select" aria-label="Filter by year"><option value="">All years</option>${[1,2,3,4].map(n=>`<option value="${n}">Year ${n}</option>`).join('')}</select></div><div id="student-results" class="student-grid">${studentCards()}</div>`;}
function studentCards(year=''){const list=queue().filter(s=>`${s.name} ${s.roll} ${s.course}`.toLowerCase().includes(q.toLowerCase())&&(!year||s.year===Number(year)));return list.map(s=>`<article class="card student-card"><div style="display:flex;justify-content:space-between;align-items:center">${avatar(s)}${badge(s.level)}</div><h3><a href="#profile/${s.id}">${esc(s.name)}</a></h3><div class="small-meta">Year ${s.year} · ${esc(s.course)}<br>${s.roll}</div>${deptStack(s.departments)}<div class="small-meta">${s.flags[0]?esc(s.flags[0].reason):'No coordination gaps detected in your permitted view.'}</div><div class="bottom"><span class="small-meta">${s.cases.length} active ${s.cases.length===1?'case':'cases'}</span><a href="#profile/${s.id}" class="text-link">View student ${icon('arrow')}</a></div></article>`).join('')||'<div class="empty">No students found. Try another name or programme.</div>';}
function profilePage(id){const s=student(id);if(!s)return '<div class="empty">Student not found. <a href="#students">Open the directory</a></div>';const f=M.flags(s,data),cases=data.cases.filter(c=>c.studentId===id),tasks=data.tasks.filter(t=>t.studentId===id);return `<a class="back-link" href="#students">${icon('arrow')} Student directory</a><section class="card profile-banner">${avatar(s,true)}<div class="grow"><div class="eyebrow">STUDENT 360 · ${s.roll}</div><h1>${esc(s.name)}</h1><p class="subtitle">Year ${s.year} · ${esc(s.course)} &nbsp; · &nbsp; ${esc(s.email)}</p></div>${badge(f.level)}<div class="button-group">${btn('Add note','note','','data-id="'+id+'"','note')}${btn('New case','intake','primary','data-id="'+id+'"','plus')}</div></section>${s.hold?`<div class="hold-banner"><div><strong>${icon('pause')} Coordinated hold is active</strong><br>Pause fee reminders. Contact Student Support before taking payment action.</div>${['coordinator','fees'].includes(role)?btn('Release hold','hold','small',`data-id="${id}"`):''}</div>`:''}<div class="tabs" style="padding-left:0"><button class="${viewTab==='overview'?'active':''}" data-action="profileTab" data-tab="overview">Overview & cases</button><button class="${viewTab==='timeline'?'active':''}" data-action="profileTab" data-tab="timeline">Shared timeline</button><button class="${viewTab==='records'?'active':''}" data-action="profileTab" data-tab="records">Department records</button></div><div class="profile-detail-grid"><div>${viewTab==='timeline'?timeline(id):viewTab==='records'?recordsPage(id):`<section class="card"><div class="content-pad"><div class="brief-label">${icon('spark')} ROLE-AWARE CASE BRIEF <span class="tag neutral">Simulated AI</span></div><p class="ai-summary">${esc(caseBrief(id))}</p>${f.flags.length?`<div class="flags-list">${f.flags.map(flag=>`<div class="flag-detail">${icon('alert')}<div><strong>${flag.label}</strong><br>${esc(flag.reason)}</div></div>`).join('')}</div>`:'<div class="notice">No coordination gaps detected in the records you can access.</div>'}<div class="button-group" style="flex-wrap:wrap">${btn('Generate handoff','handoff','small',`data-id="${id}"`,'arrows')}${btn('Case copilot','copilot','small',`data-id="${id}"`,'spark')}${!s.hold&&['coordinator','fees'].includes(role)?btn('Pause reminders','hold','small',`data-id="${id}"`,'pause'):''}</div></div></section>${id==='aanya'?`<section class="card section-gap"><div class="card-head"><h2>Original student request</h2><span class="tag neutral">Seeded text</span></div><div class="content-pad" style="padding-top:0"><p class="ai-summary" style="margin:0">“I'm struggling to pay my fees and I've missed several classes. I don't know who I should talk to.”</p></div></section>`:''}<section class="card section-gap"><div class="card-head"><h2>Connected department cases</h2><span class="count">${cases.length} records</span></div>${cases.map(caseItem).join('')||'<div class="empty">No cases available in this role.</div>'}</section>${id==='kavya'?`<section class="notice section-gap"><strong>${icon('link')} Possible related cases</strong><p style="margin:8px 0">Health Centre and Academics both recorded medical leave. Linking keeps each history intact.</p>${data.links.length?badge('Cases linked','success'):role==='coordinator'?btn('Link these cases','link','small','data-id="kavya"','link'):'Ask the coordinator to review this suggested link.'}</section>`:''}`}</div><aside class="side-stack"><section class="card"><div class="card-head"><h2>Next steps</h2>${btn('Add','addTask','small',`data-id="${id}"`,'plus')}</div>${tasks.map(t=>`<label class="task-item ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''} ${M.canEdit(t,role)?'':'disabled'} aria-label="Complete ${esc(t.title)}"><div><div class="task-title">${esc(t.title)}</div><div class="small-meta">${dept(t.department).short} · ${t.done?'Completed':`Due ${date(t.due)}`}</div></div></label>`).join('')||'<div class="empty">No tasks yet.</div>'}</section><section class="card"><div class="card-head"><h2>Department perspective</h2></div><div class="content-pad" style="padding-top:0"><label for="brief-dept" class="small-meta">Summarise the shared context for a team</label><select id="brief-dept" class="filter-select" style="width:100%;max-width:none;margin:10px 0 15px">${deptOptions(user().department)}</select>${btn('Generate summary','deptSummary','small',`data-id="${id}"`,'spark')}</div></section><section class="card"><div class="card-head"><h2>Support at a glance</h2></div><div class="content-pad" style="padding-top:0"><dl class="record-grid" style="grid-template-columns:1fr;margin:0"><div class="record-field"><dt>Departments involved</dt><dd>${f.departments.map(d=>dept(d).short).join(' · ')||'No active cases'}</dd></div><div class="record-field"><dt>Support coordinator</dt><dd>Meera Iyer</dd></div><div class="record-field"><dt>Priority score</dt><dd>${f.score} · ${f.flags.length} visible signals</dd></div></dl></div></section></aside></div>`;}
function caseItem(c){return `<div class="case-item"><div class="dept-icon" style="color:${dept(c.department).color}">${icon(dept(c.department).icon)}</div><div class="grow"><div class="small-meta">${esc(c.id)} · ${esc(dept(c.department).name)}</div><h3>${esc(c.summary)}</h3>${c.access==='redacted'?`<div class="restricted">${icon('lock')} Restricted to Counselling</div>`:c.privateNote?`<div class="private-note">${icon('shield')} ${esc(c.privateNote)}</div>`:''}${c.originalRequest&&c.access==='full'?`<div class="small-meta">Original request: “${esc(c.originalRequest)}”</div>`:''}<div class="small-meta">Opened ${date(c.openedAt)} · ${c.owner} · ${c.status==='Resolved'?'Completed':M.days(c.openedAt)>C.slaDays?'Beyond demo SLA target':'Within demo SLA target'}</div>${c.appointmentRequestedAt&&!c.appointmentBooked&&M.canEdit(c,role)?btn('Book appointment','appointment','small',`data-id="${c.id}"`,'calendar'):c.appointmentBooked?badge(`Booked ${date(c.appointmentDate)}`,'success'):''}${c.approved&&!c.shared?btn('Send to Exams','handoff','small',`data-id="${c.studentId}" data-case="${c.id}" data-to="academics"`,'arrows'):''}</div>${M.canEdit(c,role)?`<select class="filter-select" data-status="${c.id}" aria-label="Status for ${esc(c.id)}">${['Pending','In progress','Waiting on student','Resolved'].map(status=>`<option ${status===c.status?'selected':''}>${status}</option>`).join('')}</select>`:badge(c.status)}</div>`;}
function caseBrief(id){const s=student(id),cs=data.cases.filter(c=>c.studentId===id),open=cs.filter(c=>c.status!=='Resolved'),f=M.flags(s,data),pending=data.tasks.filter(t=>t.studentId===id&&!t.done);return `${s.name.split(' ')[0]} has ${open.length} active support ${open.length===1?'case':'cases'} across ${f.departments.length} departments. ${open.length?open.filter(c=>c.access==='full').map(c=>c.summary).slice(0,3).join('. ')+'. ':''}${cs.some(c=>c.access==='redacted')?'Counselling is involved; sensitive details remain restricted. ':''}${role==='counsellor'&&cs.some(c=>c.privateNote)?cs.filter(c=>c.privateNote).map(c=>c.privateNote).join(' ')+' ':''}${pending.length?`Next: ${pending[0].title.toLowerCase()}.`:'No outstanding tasks in your permitted view.'}`;}
function timeline(id){const events=data.events.filter(e=>e.studentId===id).sort((a,b)=>new Date(b.at)-new Date(a.at));return `<section class="card"><div class="card-head"><div><h2>One shared timeline</h2><p class="card-description">Every action is added to the event history.</p></div>${btn('Add note','note','small',`data-id="${id}"`,'plus')}</div><div class="timeline">${events.map(e=>`<div class="timeline-event"><time datetime="${e.at}">${date(e.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · ${relative(e.at)}</time><div>${e.access==='redacted'?icon('lock'):''} ${esc(e.text)}</div><div class="small-meta">${esc(dept(e.department).short)} · ${esc(e.actor)}</div></div>`).join('')||'<div class="empty">No visible events yet.</div>'}</div></section>`;}
function recordsPage(id){const records=data.records.filter(r=>r.studentId===id);return `<section class="card"><div class="card-head"><div><h2>Student database lookup</h2><p class="card-description">Department records available to ${esc(user().short)}.</p></div></div><div class="content-pad" style="padding-top:0">${records.length?`<label class="form-field">Department<select id="record-department">${records.map(r=>`<option value="${r.department}" ${r.department===user().department?'selected':''}>${dept(r.department).name}</option>`).join('')}</select></label><div id="record-fields">${recordFields(records.find(r=>r.department===user().department)||records[0])}</div>`:'<div class="notice">No general department database records are available to this role. Use the authorised case notes above.</div>'}</div></section>`;}
function recordFields(r){return `<dl class="record-grid">${Object.entries(r.fields).map(([k,v])=>`<div class="record-field"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="form-help">Fictional register · ${dept(r.department).name} · Available without an external connection.</p>`;}
function casesPage(){return heading('A single view of every case.','Keep department ownership clear and the student journey connected.',btn('New case','intake','primary','','plus'))+notice()+`<section class="card"><div class="card-head"><h2>Case register</h2><span class="count">${data.cases.length} visible cases</span></div><div class="filters"><label class="search-box">${icon('search')}<input id="case-search" placeholder="Search students, case IDs or summaries" aria-label="Search cases"></label><select id="case-dept" class="filter-select" aria-label="Filter cases by department">${deptOptions('',true)}</select><select id="case-status-filter" class="filter-select" aria-label="Filter cases by status"><option value="">All statuses</option><option>Pending</option><option>In progress</option><option>Waiting on student</option><option>Resolved</option></select></div><div id="case-results">${caseResults()}</div></section>`;}
function caseResults(){const query=$('#case-search')?.value?.toLowerCase()||'',department=$('#case-dept')?.value||'',status=$('#case-status-filter')?.value||'';return data.cases.filter(c=>`${c.id} ${c.summary} ${student(c.studentId)?.name}`.toLowerCase().includes(query)&&(!department||department===c.department)&&(!status||status===c.status)).map(c=>`<div style="padding:12px 22px 0"><a class="text-link" href="#profile/${c.studentId}">${esc(student(c.studentId)?.name)} ${icon('arrow')}</a></div>${caseItem(c)}`).join('')||'<div class="empty">No cases match these filters.</div>';}
function handoffsPage(){return heading('Pass the context. Keep the connection.','A handoff stays pending until the receiving team accepts ownership.',btn('New handoff','handoff','primary','','arrows'))+notice()+`<div class="tabs" style="margin-bottom:20px"><button class="active">All handoffs · ${data.handoffs.length}</button></div>${data.handoffs.map(h=>`<section class="card handoff-card"><div><div class="person"><div>${avatar(student(h.studentId))}</div><div><a class="person-name" href="#profile/${h.studentId}">${esc(student(h.studentId)?.name)}</a><div class="small-meta">${h.id} · Sent ${relative(h.createdAt)}</div></div></div><div class="handoff-journey"><span>${dept(h.from).name}</span>${icon('arrow')}<strong>${dept(h.to).name}</strong></div><p class="handoff-brief">${esc(h.brief)}</p></div><div style="display:flex;flex-direction:column;align-items:flex-end;gap:12px">${badge(h.status)}${h.status==='Pending'&&M.days(h.createdAt)>C.referralDays?`<span class="tag urgent">${M.days(h.createdAt)} days waiting · over ${C.referralDays}-day target</span>`:''}${h.status==='Pending'&&(role==='coordinator'||user().department===h.to)?btn('Accept handoff','accept','primary small',`data-id="${h.id}"`,'check'):h.status==='Pending'?'<span class="small-meta">Awaiting receiving team</span>':`<span class="small-meta">Accepted ${date(h.acceptedAt)}</span>`}</div></section>`).join('')||'<div class="card empty">No handoffs yet. Create one from a student workspace.</div>'}`;}
function departmentsPage(selected){if(selected){const d=dept(selected),cs=data.cases.filter(c=>c.department===selected),pending=data.handoffs.filter(h=>h.to===selected&&h.status==='Pending');return `<a class="back-link" href="#departments">${icon('arrow')} All departments</a>`+heading(d.name,'Your department’s work, with the shared student context.',btn('New case','intake','primary','','plus'))+`<div class="metrics">${[['Active cases',cs.filter(c=>c.status!=='Resolved').length],['Students',new Set(cs.map(c=>c.studentId)).size],['Pending referrals',pending.length],['Resolved',cs.filter(c=>c.status==='Resolved').length]].map(([label,n])=>`<div class="metric"><div class="metric-top">${label}</div><div class="metric-value">${n}</div></div>`).join('')}</div><section class="card"><div class="card-head"><h2>Department cases</h2></div>${cs.map(c=>`<div style="padding:12px 22px 0"><a href="#profile/${c.studentId}" class="text-link">${student(c.studentId)?.name} ${icon('arrow')}</a></div>${caseItem(c)}`).join('')||'<div class="empty">No cases in this department yet. The department is ready for a referral.</div>'}</section>`;}
 return heading('Twelve departments. Shared understanding.','Every team keeps its expertise. Everyone works from the same context.')+notice()+`<div class="departments-grid">${data.departments.map(d=>{const cases=data.cases.filter(c=>c.department===d.id);return `<a href="#departments/${d.id}" class="card department-card"><div style="display:flex;justify-content:space-between;align-items:center"><div class="dept-icon" style="color:${d.color}">${icon(d.icon)}</div>${badge(d.seeded?'Seeded team':cases.length?'Optional demo':'Ready to connect','neutral')}</div><h3>${d.name}</h3><div class="small-meta">${d.id==='wellbeing'||d.id==='grievance'?'Restricted information · role-aware visibility':'Shared status · department-owned actions'}</div><div class="department-stats"><div><strong>${cases.filter(c=>c.status!=='Resolved').length}</strong><span>Active cases</span></div><div><strong>${new Set(cases.map(c=>c.studentId)).size}</strong><span>Students</span></div><div style="margin-left:auto;align-self:center">${icon('arrow')}</div></div></a>`;}).join('')}</div>`;}
function insightsPage(){const ranked=queue(),longest=ranked.filter(s=>s.cases.length).sort((a,b)=>b.wait-a.wait).slice(0,5),departments=data.departments.map(d=>({...d,count:activeCases().filter(c=>c.department===d.id).length})).filter(d=>d.count);return heading('Make the gaps visible.','A leadership snapshot of demand, waiting time and joined-up support.',btn('Export snapshot','export','','','download'))+notice()+metrics()+`<div class="insights-grid"><section class="card"><div class="card-head"><h2>Open cases by department</h2><span class="small-meta">Current demo state</span></div><div class="content-pad">${departments.map(d=>`<div class="chart-row"><span>${d.short}</span><div class="bar-track"><div class="bar-fill" style="width:${d.count/Math.max(...departments.map(x=>x.count))*100}%;background:${d.color}88"></div></div><b>${d.count}</b></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>Longest open journeys</h2></div>${longest.map(s=>`<div class="handoff-mini"><div class="person">${avatar(s)}<div><a class="person-name" href="#profile/${s.id}">${s.name}</a><div class="small-meta">${s.departments.length} departments</div></div></div><strong style="font-size:13px">${s.wait} days</strong></div>`).join('')}</section></div><section class="card section-gap"><div class="card-head"><h2>How attention is calculated</h2><span class="tag neutral">Transparent rules</span></div><div class="content-pad" style="padding-top:0"><div class="record-grid">${[[`Referral pending > ${C.referralDays} days`,`${C.weights.referral} points · Receiving department has not accepted.`],[`First appointment waiting > ${C.appointmentDays} days`,`${C.weights.appointment} points · No booking has been recorded.`],[`${C.departmentCount}+ departments involved`,`${C.weights.multi} points · Shared coordination is needed.`],['Reminder during sensitive support',`${C.weights.reminder} points · A coordinated hold may be appropriate.`],['Approved accommodation not shared',`${C.weights.unshared} points · Exams has not accepted the handoff.`],['Wait time and department count','Add up to 35 waiting-day points plus active department count. No flag means a score of zero.']].map(([a,b])=>`<div class="record-field"><h3>${a}</h3><div class="small-meta">${b}</div></div>`).join('')}</div><p class="form-help" style="margin-top:18px">Scores support staff prioritisation. They are not clinical assessments or autonomous decisions. All thresholds are defined in config.js.</p></div></section>`;}
const policies=[['fees','Fee support & coordinated holds','When a fee reminder overlaps an open sensitive support case, a coordinator or fee officer may pause reminders. Contact Student Support, review available assistance and agree a follow-up. A hold remains visible to Fees without disclosing counselling notes.','DEMO-POL-01'],['wellbeing','Warm referral guidance','Send a short, permission-filtered context brief to the receiving team. Ownership stays pending until they accept. Follow up when a referral has waited more than seven days.','DEMO-POL-02'],['academics','Academic flexibility & accommodations','Coordinate attendance support with the academic team. Approved accessibility adjustments should be handed to Exams, and the receiving team must acknowledge them.','DEMO-POL-03'],['affairs','Student support & privacy','Students should not repeat their story to every team. Share operational context, redact counselling content for other roles and hide confidential grievance records from unauthorised roles.','DEMO-POL-04']];
function knowledgePage(){return heading('A little guidance for the next step.','A small, searchable reference library for this fictional university demo.')+`<div class="notice">These are illustrative demo policies, not official IGDTUW guidance. Answers use this local reference library; no external AI or RAG service is connected.</div><label class="search-box" style="margin-bottom:20px">${icon('search')}<input id="knowledge-search" aria-label="Search demo knowledge" placeholder="Search fee support, referrals, privacy or accommodations..."></label><div class="knowledge-grid" id="knowledge-results">${policyCards('')}</div>`;}
function policyCards(query){return policies.filter(p=>p.join(' ').toLowerCase().includes(query.toLowerCase())).map(([d,title,text,source])=>`<article class="card knowledge-item" id="${source}">${badge(dept(d).short)}<h2>${title}</h2><p>${text}</p><a href="#knowledge" class="text-link" data-action="policy" data-id="${source}">${source} · Fictional policy ${icon('arrow')}</a></article>`).join('')||'<div class="empty">No matching demo policy. Try “fees”, “referral” or “privacy”.</div>';}
function studentPage(){
 const s=student('aanya'),cs=data.cases.filter(c=>c.studentId===s.id&&!c.studentSubmitted),grievances=data.cases.filter(c=>c.studentId===s.id&&c.studentSubmitted).sort((a,b)=>new Date(b.openedAt)-new Date(a.openedAt));
 return heading(`Hello, ${s.name.split(' ')[0]}.`,'Your support is connected, so you don’t have to start over.',btn('Add a grievance','studentGrievance','primary','','plus'))+notice()+
 `<section class="student-grievance-prompt"><div class="student-grievance-icon">${icon('note')}</div><div><h2>Have another concern? We’re here to listen.</h2><p>Write it, say it, or try a fictional example. Review your message before submitting.</p><div class="button-group">${btn('Write a grievance','studentGrievance','primary small','','note')}${btn('Use voice','studentGrievance','small','data-mode="voice"','mic')}${btn('Use demo','studentGrievance','small','data-mode="demo"','spark')}</div></div></section>
 <div class="student-support-grid"><section class="card student-status">${avatar(s,true)}<h2>Your support journey</h2><p>Your university support teams are coordinating the next steps.</p>${s.hold?'<div class="notice">Your fee reminders are paused while the support team reviews your request.</div>':''}${cs.map(c=>`<div class="handoff-mini" style="padding-left:0;padding-right:0"><div><strong>${dept(c.department).name}</strong><p class="small-meta" style="margin:6px 0">${esc(c.summary)}</p></div>${badge(c.status)}</div>`).join('')}<div class="notice" style="margin-top:20px">Demo account · Student registration and university authentication are simulated.</div></section>
 <section class="card student-grievances"><div class="card-head"><div><h2>Your grievances</h2><p class="card-description">Visible to you and the Grievance Officer in this demo.</p></div><span class="count">${grievances.length}</span></div>${grievances.length?grievances.map(c=>`<details class="student-grievance-record" ${grievances.length===1?'open':''}><summary><span>${esc(c.summary)}</span>${badge(c.status)}</summary><div class="student-grievance-content"><p>${esc(c.originalRequest)}</p><div class="small-meta">Submitted ${date(c.openedAt)} · ${esc(c.id)}</div><div class="restricted">${icon('lock')} Grievance & Internal Complaints</div></div></details>`).join(''):`<div class="empty">${icon('shield')}No grievances submitted yet.<br>Your new submissions and their status will appear here.</div>`}<div class="card-footer"><span>Saved locally with the fictional demo records.</span></div></section></div>`;
}
const grievanceExample={title:'Follow-up on a hostel maintenance concern',text:'I reported a broken study-room light in my hostel a week ago, but I have not received an update. It is making evening study difficult. Could the team review my request and let me know the next steps?'};
let grievanceRecognition=null;
function grievanceForm(mode='text'){
 if(role!=='student')return toast('Switch to the student demo to submit your own grievance.');
 modal('Tell us what needs attention',`<form id="student-grievance-form"><div class="modal-body"><div class="notice">Submitting as <strong>${esc(user().user)}</strong>. This fictional demo stores your message locally. Grievance details are hidden from other staff roles.</div><div class="form-field"><label for="grievance-title">Give your concern a short title</label><input id="grievance-title" name="title" required minlength="3" maxlength="120" placeholder="For example, an unresolved campus service request" value="${mode==='demo'?esc(grievanceExample.title):''}"></div><div class="form-field"><label for="grievance-text">What would you like us to know?</label><textarea id="grievance-text" name="text" required minlength="10" maxlength="3000" placeholder="Describe what happened and the support you would like.">${mode==='demo'?esc(grievanceExample.text):''}</textarea><small>10–3,000 characters. You can edit dictated text before submitting.</small></div><div class="button-group grievance-input-options">${btn('Record voice','grievanceVoice','small','id="grievance-voice-button"','mic')}${btn('Use demo example','grievanceExample','small','','spark')}</div><p class="grievance-voice-status" id="grievance-voice-status" role="status" aria-live="polite">${mode==='demo'?'Example filled in. Review or edit it, then submit.':'You can type directly or dictate using your microphone.'}</p><p class="form-help">Voice input needs browser support and microphone permission, and may use your browser’s online speech service. Text and the demo example work without it.</p></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="btn primary">Submit grievance ${icon('arrow')}</button></div></form>`);
 if(mode==='voice')startGrievanceVoice();
}
function startGrievanceVoice(){
 const status=$('#grievance-voice-status'),button=$('#grievance-voice-button'),field=$('#grievance-text');if(!status||!button||!field)return;
 if(grievanceRecognition){grievanceRecognition.stop();return;}
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!Speech){status.textContent='Voice input isn’t supported in this browser. You can type your grievance or use the demo example.';return;}
 try{const recognition=new Speech();grievanceRecognition=recognition;recognition.lang='en-IN';recognition.interimResults=true;recognition.continuous=false;const existing=field.value.trim();let hadError=false;
  recognition.onstart=()=>{if(!$('#grievance-voice-status'))return;status.textContent='Listening… Speak your concern, then select Stop recording.';button.innerHTML=icon('pause')+'Stop recording';};
  recognition.onresult=event=>{if(!$('#grievance-text')||!$('#modal').open)return;const words=Array.from(event.results).map(result=>result[0].transcript).join(' ');field.value=(existing+(existing?'\n':'')+words).slice(0,3000);};
  recognition.onerror=event=>{hadError=true;if(event.error==='aborted')return;if($('#grievance-voice-status'))status.textContent=event.error==='not-allowed'?'Microphone permission was not granted. Please type your grievance or use the demo example.':event.error==='no-speech'?'No speech was detected. Try again, type your concern, or use the demo example.':'Voice input is unavailable. Your existing text is safe; continue by typing or use the demo example.';};
  recognition.onend=()=>{if(grievanceRecognition===recognition)grievanceRecognition=null;if($('#grievance-voice-button'))button.innerHTML=icon('mic')+'Record voice';if(!hadError&&$('#grievance-voice-status'))status.textContent='Recording finished. Review your text and add a title before submitting.';};
  status.textContent='Starting microphone…';recognition.start();
 }catch{grievanceRecognition=null;button.innerHTML=icon('mic')+'Record voice';status.textContent='Voice input could not start. You can type your grievance or use the demo example.';}
}
window.addEventListener('hashchange',()=>{q='';deptFilter='';priorityFilter='';viewTab='overview';render();window.scrollTo(0,0);});window.addEventListener('connext-change',render);window.addEventListener('storage',e=>{if(e.key===C.storageKey){M.reload();render();toast('Updated from another demo tab.');}});window.addEventListener('connext-storage-error',()=>toast('Browser storage is unavailable. Changes will last for this session.'));
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;sessionStorage.setItem('connext-role',role);if($('#modal').open)$('#modal').close();chat=[];viewTab='overview';if(role==='student')go('student');else if(route==='student')go('overview');else render();toast(`Viewing as ${user().short}`);}if(['department-filter','priority-filter','queue-sort'].includes(e.target.id)){if(e.target.id==='department-filter')deptFilter=e.target.value;if(e.target.id==='priority-filter')priorityFilter=e.target.value;if(e.target.id==='queue-sort')sort=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='queue-search'){q=e.target.value;const rows=queueRows(route==='attention'?0:5);$('#queue-body').innerHTML=rows.html;$('#queue-count').textContent=`Showing ${Math.min(route==='attention'?rows.total:5,rows.total)} of ${rows.total} flagged students`;}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const action=el.dataset.action;if(action==='profile')go(`profile/${el.dataset.id}`);else if(action==='menu')$('#sidebar').classList.toggle('open');else if(action==='queueTab'){queueTab=el.dataset.tab;render();}else handleAction(action,el);});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();$('#global-search input')?.focus();}});
document.addEventListener('submit',e=>{if(e.target.id==='global-search'){e.preventDefault();const term=new FormData(e.target).get('query');go('students');setTimeout(()=>{q=term;render();},0);}else handleSubmit(e);});
function modal(title,body,footer=''){const dialog=$('#modal');dialog.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function handleAction(action,el){const id=el.dataset.id||route.split('/')[1]||'aanya';
 if(action==='studentGrievance')return grievanceForm(el.dataset.mode||'text');
 if(action==='grievanceVoice')return startGrievanceVoice();
 if(action==='grievanceExample'){if(grievanceRecognition){grievanceRecognition.abort();grievanceRecognition=null;}$('#grievance-title').value=grievanceExample.title;$('#grievance-text').value=grievanceExample.text;$('#grievance-voice-status').textContent='Example filled in. Review or edit it, then submit.';return;}
 if(action==='close')return $('#modal').close();
 if(action==='profileTab'){viewTab=el.dataset.tab;return render();}
 if(action==='about')return modal('Built for a joined-up demo',`<div class="modal-body"><div class="notice">All names, student records and policies are fictional.</div><p class="ai-summary">Connext connects 12 university departments around one student story. This version runs entirely in your browser, with a hardcoded dataset and simulated AI.</p><ul class="bullet-list"><li>Role switching demonstrates full, redacted and hidden records.</li><li>Changes stay in this browser and sync across tabs on the same origin.</li><li>Clerk, Groq, ServiceNow APIs and a real database are not connected.</li><li>The browser contains the fictional seed data. This is not a security boundary for real personal information.</li><li>Reset recreates the 10 student stories with dates relative to today.</li></ul></div>`,btn('Reset demo','reset','danger','','refresh')+btn('Got it','close','primary'));
 if(action==='reset'){M.reset();q='';viewTab='overview';$('#modal').close();go('overview');return toast('Demo reset. All 10 student stories are ready.');}
 if(action==='notifications')return modal('Your support updates',`<div class="modal-body"><div class="activity-list" style="padding:0">${activityList(6)}</div></div>`,btn('Close','close','primary'));
 if(action==='intake'){intakeDraft=null;return modal('Create a connected support case',`<form id="intake-form"><div class="modal-body"><div class="notice">Demo intake uses a deterministic, offline fallback. Review the proposed routing before creating the case.</div><div class="form-field"><label for="intake-student">Student</label><select id="intake-student" name="studentId">${studentOptions(id)}</select></div><div class="form-field"><label for="intake-text">What does the student need help with?</label><textarea id="intake-text" name="text" required minlength="10" placeholder="I’m struggling to pay my fees and have been missing classes. I’m not sure who to talk to."></textarea><small>One request becomes connected department records and clear next steps.</small></div><div class="button-group">${btn('Use an example','intakeExample','small','','note')}${btn('Voice input','voice','small','','mic')}</div><div id="intake-result"></div></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="btn primary">${icon('spark')} Analyse request</button></div></form>`);}
 if(action==='intakeExample'){$('#intake-text').value='I am struggling to pay my fees and have missed several classes. My scholarship is delayed. Can someone help me coordinate support?';return;}
 if(action==='voice'){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)return toast('Voice input is not supported in this browser. Please type your request.');try{const recognition=new Speech();recognition.lang='en-IN';recognition.onresult=e=>{$('#intake-text').value=e.results[0][0].transcript;toast('Voice captured. Review the text before analysing.');};recognition.onerror=()=>toast('Microphone unavailable. You can still type your request.');recognition.start();toast('Listening…');}catch{toast('Voice input unavailable. Please type your request.');}return;}
 if(action==='createIntake'){if(!intakeDraft)return;const s=student(intakeDraft.studentId);if(mutate('intake',intakeDraft,`Connected case and department tasks created for ${s.name.split(' ')[0]}.`)){$('#modal').close();go(`profile/${s.id}`);}return;}
 if(action==='note'){const options=role==='coordinator'?deptOptions('affairs'):`<option value="${user().department}">${dept(user().department).name}</option>`;return modal('Add to the shared timeline',`<form id="note-form"><div class="modal-body"><input type="hidden" name="studentId" value="${id}"><div class="form-field"><label>Department</label><select name="department">${options}</select></div><div class="form-field"><label for="note-text">Note for ${esc(student(id)?.name)}</label><textarea id="note-text" name="text" required placeholder="Add the context your colleagues need for the next step."></textarea></div>${['counsellor','grievance'].includes(role)?'<label class="task-item"><input type="checkbox" name="restricted" checked> Restrict this note to my authorised team</label>':'<div class="notice">Shared notes are visible across departments. Keep sensitive counselling or grievance details in the authorised team’s restricted notes.</div>'}</div><div class="modal-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">Save note</button></div></form>`);}
 if(action==='addTask'){const tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10);return modal('Add a next step',`<form id="task-form"><div class="modal-body"><input type="hidden" name="studentId" value="${id}"><div class="form-field"><label for="task-title">Task</label><input id="task-title" name="title" required placeholder="What needs to happen next?"></div><div class="form-row"><div class="form-field"><label>Responsible department</label><select name="department">${role==='coordinator'?deptOptions('affairs'):`<option value="${user().department}">${dept(user().department).name}</option>`}</select></div><div class="form-field"><label>Follow-up date</label><input type="date" name="due" value="${tomorrow}" required min="${new Date().toISOString().slice(0,10)}"></div></div><p class="form-help">This is a local follow-up task. No email or external reminder is sent.</p></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="btn primary">Add task</button></div></form>`);}
 if(action==='hold')return mutate('hold',{studentId:id},student(id).hold?'Coordinated hold released.':'Reminders paused. The hold is visible to Fees.');
 if(action==='accept')return mutate('accept',{id},'Handoff accepted. Ownership and timeline updated.');
 if(action==='link'){const ids=data.cases.filter(c=>c.studentId==='kavya'&&c.duplicateGroup).map(c=>c.id);return mutate('link',{ids},'Cases linked. Both department histories are preserved.');}
 if(action==='handoff'){const s=student(id)||data.students[0],related=data.cases.find(c=>c.id===el.dataset.case),to=el.dataset.to||'wellbeing',from=related?.department||user().department||'affairs';return modal('A warm handoff, with context',`<form id="handoff-form"><div class="modal-body"><div class="form-field"><label>Student</label><select name="studentId" id="handoff-student">${studentOptions(s.id)}</select></div><input type="hidden" name="caseId" value="${related?.id||''}"><div class="form-row"><div class="form-field"><label>From</label><select name="from">${role==='coordinator'?deptOptions(from):`<option value="${user().department}">${dept(user().department).name}</option>`}</select></div><div class="form-field"><label>Receiving department</label><select name="to" id="handoff-to">${deptOptions(to===from?'academics':to)}</select></div></div><div class="form-field"><label for="handoff-brief">Context brief · simulated AI</label><textarea id="handoff-brief" name="brief" required>${esc(publicHandoff(s.id))}</textarea><small>Review the brief before sending. Share only operational context appropriate for the receiving team.</small></div><div class="notice">The handoff will remain pending until the receiving department accepts it. After ${C.referralDays} days, the gap detector highlights the wait.</div></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="btn primary">Send handoff ${icon('arrow')}</button></div></form>`);}
 if(action==='appointment'){const c=data.cases.find(c=>c.id===id),min=new Date(Date.now()+86400000).toISOString().slice(0,16);return modal('Book the first appointment',`<form id="appointment-form"><div class="modal-body"><input type="hidden" name="id" value="${id}"><p class="ai-summary">Offer ${esc(student(c.studentId).name)} a first counselling appointment. This creates a demo booking and clears the waiting-time flag.</p><div class="form-field"><label>Appointment date and time</label><input type="datetime-local" name="date" required min="${new Date().toISOString().slice(0,16)}" value="${min}"></div></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="btn primary">Confirm demo booking</button></div></form>`);}
 if(action==='briefing'){const list=queue().filter(s=>s.score).slice(0,5);return modal('Your daily support briefing',`<div class="modal-body"><div class="brief-label">${icon('spark')} ${date(new Date(),{weekday:'long',day:'numeric',month:'long'})} · SIMULATED AI</div><p class="ai-summary">${list.length} students to start with. This briefing uses only the records visible to ${esc(user().short)}.</p>${list.map((s,i)=>`<div class="brief-section"><h3>${i+1}. ${s.name} ${badge(s.level)}</h3><p>${esc(s.flags[0].reason)}</p><p><strong>Next step:</strong> ${esc(data.tasks.find(t=>t.studentId===s.id&&!t.done)?.title||'Coordinate a shared plan with the involved teams.')}</p></div>`).join('')||'<div class="notice">No flagged students in your current view.</div>'}</div>`,btn('Close','close','primary'));}
 if(action==='deptSummary'){const department=$('#brief-dept').value;const safe=M.get(role);const cs=safe.cases.filter(c=>c.studentId===id);return modal(`${dept(department).short} · case perspective`,`<div class="modal-body"><div class="brief-label">${icon('spark')} SIMULATED AI · PERMISSION-FILTERED</div><p class="ai-summary">${esc(student(id).name)} is working with ${new Set(cs.map(c=>c.department)).size} departments. ${dept(department).name} should review its assigned work and coordinate with Student Support.</p><div class="brief-section"><h3>Shared operational context</h3><ul class="bullet-list">${cs.map(c=>`<li>${dept(c.department).short}: ${c.status}${c.access==='redacted'?' · Sensitive details restricted':` · ${esc(c.summary)}`}</li>`).join('')}</ul></div><div class="brief-section"><h3>Next steps for this department</h3><ul class="bullet-list">${safe.tasks.filter(t=>t.studentId===id&&t.department===department&&!t.done).map(t=>`<li>${esc(t.title)}</li>`).join('')||'<li>Review the shared timeline and confirm whether departmental action is needed.</li>'}</ul></div></div>`,btn('Close','close','primary'));}
 if(action==='copilot'){chat=[];return modal('Case copilot',`<div class="modal-body"><div class="notice">Local simulated assistant · Uses the currently visible case records. It does not make clinical or eligibility decisions.</div><div class="copilot-conversation" id="chat"><div class="message">I can help you review ${esc(student(id).name.split(' ')[0])}’s next steps, timeline or a handoff.</div></div><div class="suggestions">${['What is pending?','Summarise the timeline','Suggest the next action','Prepare a handoff'].map(text=>`<button data-action="suggestion" data-id="${id}" data-text="${text}">${text}</button>`).join('')}</div><form id="copilot-form"><input type="hidden" name="studentId" value="${id}"><div class="form-field" style="margin:0"><label for="copilot-question">Ask about this case</label><div style="display:flex;gap:8px"><input id="copilot-question" name="question" required placeholder="What should I follow up on?"><button type="submit" class="btn primary" aria-label="Ask copilot">${icon('arrow')}</button></div></div></form></div>`);}
 if(action==='suggestion')return answerCopilot(id,el.dataset.text);
 if(action==='policy'){const p=policies.find(p=>p[3]===id);return modal(p[1],`<div class="modal-body"><span class="tag neutral">${p[3]} · Fictional policy</span><p class="ai-summary">${p[2]}</p></div>`,btn('Close','close','primary'));}
 if(action==='export'){const rows=[['Student','Attention level','Score','Days waiting','Departments','Visible reasons'],...queue().map(s=>[s.name,s.level,s.score,s.wait,s.departments.map(d=>dept(d).short).join('; '),s.flags.map(f=>f.reason).join('; ')])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='connext-demo-snapshot.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Role-filtered snapshot exported.');}
}
function publicHandoff(id){const s=student(id),cs=data.cases.filter(c=>c.studentId===id&&c.status!=='Resolved');return `${s.name} has active support with ${[...new Set(cs.map(c=>dept(c.department).short))].join(', ')||'Student Affairs'}. Please review the shared operational status, contact the student once and confirm your next action. Sensitive notes remain with their authorised team. Accept this handoff to confirm ownership.`;}
function answerCopilot(id,question){const t=question.toLowerCase(),safe=M.get(role),tasks=safe.tasks.filter(x=>x.studentId===id&&!x.done);let answer;if(/handoff/.test(t))answer=publicHandoff(id);else if(/timeline|happened|today/.test(t))answer=safe.events.filter(e=>e.studentId===id).sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,5).map(e=>`${date(e.at)} · ${e.text}`).join('\n');else if(/pending|task|next|follow/.test(t))answer=tasks.length?tasks.map(task=>`• ${task.title} — ${dept(task.department).short}, due ${date(task.due)}.`).join('\n'):'No outstanding tasks are visible. Check the timeline and agree a follow-up with Student Support.';else if(/fee|policy|financial/.test(t))answer=policies[0][2]+'\nSource: DEMO-POL-01 (fictional demo policy).';else if(/summary|summari|brief/.test(t))answer=caseBrief(id);else answer='This offline demo supports pending tasks, timeline summaries, suggested next actions, handoffs and fee-support guidance. Try one of the suggested questions.';chat.push({question,answer});$('#chat').innerHTML=chat.map(m=>`<div class="message user">${esc(m.question)}</div><div class="message">${esc(m.answer)}</div>`).join('');$('#chat').scrollTop=$('#chat').scrollHeight;$('#copilot-question').value='';}
function handleSubmit(e){const form=e.target;if(!['intake-form','note-form','task-form','handoff-form','appointment-form','copilot-form'].includes(form.id))return;e.preventDefault();const f=Object.fromEntries(new FormData(form));if(form.id==='intake-form'){const result=M.intake(f.text);intakeDraft={...f,...result};const related=data.cases.filter(c=>c.studentId===f.studentId&&c.status!=='Resolved'&&result.departments.includes(c.department));$('#intake-result').innerHTML=`<div class="intake-result"><strong>${icon('check')} Proposed routing is ready</strong><p>${esc(result.summary)}</p><div class="button-group" style="flex-wrap:wrap">${result.departments.map(d=>badge(dept(d).short,'success')).join('')}</div><p><strong>${result.priority} priority</strong> · ${result.departments.length} department tasks will be created.</p>${related.length?`<div class="notice">${icon('link')} ${related.length} related open ${related.length===1?'case exists':'cases exist'} for this student. Review their profile if this is a duplicate. Creating this request keeps it separate; nothing is merged automatically.</div>`:''}${btn('Create connected case','createIntake','primary','','plus')}</div>`;return;}
 if(form.id==='copilot-form')return answerCopilot(f.studentId,f.question);
 const action=form.id==='note-form'?'note':form.id==='task-form'?'addTask':form.id==='handoff-form'?'handoff':'appointment';if(action==='note')f.restricted=f.restricted==='on';if(action==='handoff'&&!f.caseId)delete f.caseId;
 if(mutate(action,f,action==='note'?'Note added to the shared timeline.':action==='addTask'?'Next step added.':action==='handoff'?'Handoff sent. Awaiting acceptance.':'Demo appointment booked.'))$('#modal').close();
}
document.addEventListener('change',e=>{if(e.target.dataset.status)mutate('status',{id:e.target.dataset.status,status:e.target.value},'Case status and shared timeline updated.');if(e.target.dataset.task)mutate('task',{id:e.target.dataset.task,done:e.target.checked},e.target.checked?'Task completed.':'Task reopened.');if(e.target.id==='student-year')$('#student-results').innerHTML=studentCards(e.target.value);if(['case-dept','case-status-filter'].includes(e.target.id))$('#case-results').innerHTML=caseResults();if(e.target.id==='record-department')$('#record-fields').innerHTML=recordFields(data.records.find(r=>r.studentId===route.split('/')[1]&&r.department===e.target.value));if(e.target.id==='handoff-student'){$('#handoff-brief').value=publicHandoff(e.target.value);$('#handoff-form input[name="caseId"]').value='';}});
document.addEventListener('input',e=>{if(e.target.id==='student-search'){q=e.target.value;$('#student-results').innerHTML=studentCards($('#student-year').value);}if(e.target.id==='case-search')$('#case-results').innerHTML=caseResults();if(e.target.id==='knowledge-search')$('#knowledge-results').innerHTML=policyCards(e.target.value);if(['intake-text','intake-student'].includes(e.target.id)){intakeDraft=null;if($('#intake-result'))$('#intake-result').innerHTML='';}});
document.addEventListener('submit',e=>{if(e.target.id!=='student-grievance-form')return;e.preventDefault();const payload=Object.fromEntries(new FormData(e.target));try{M.mutate('studentGrievance',payload,role);$('#modal').close();go('student');toast('Grievance submitted. Track its status under Your grievances.');}catch(error){toast(error.message);}});
$('#modal').addEventListener('close',()=>{if(grievanceRecognition){const recognition=grievanceRecognition;grievanceRecognition=null;recognition.abort();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const bounds=$('#modal').getBoundingClientRect();if(e.clientX<bounds.left||e.clientX>bounds.right||e.clientY<bounds.top||e.clientY>bounds.bottom)$('#modal').close();}});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'get_attention_queue',title:'Read attention queue',description:'Read the visible priority queue with reasons for the current demo role.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object.');return queue().filter(s=>s.score>0).map(s=>({id:s.id,name:s.name,priority:s.level,reasons:s.flags.map(f=>f.reason)}));}},{name:'open_student_workspace',title:'Open student workspace',description:'Navigate to a visible student workspace. Does not change any case records.',inputSchema:{type:'object',properties:{studentId:{type:'string'}},required:['studentId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='studentId')||typeof input.studentId!=='string'||!student(input.studentId))throw new Error('Unknown student.');location.hash=`profile/${input.studentId}`;render();return {studentId:input.studentId,opened:true};}},{name:'complete_department_task',title:'Complete task',description:'Complete an existing demo task the current role owns. Appends an event and updates the visible workspace.',inputSchema:{type:'object',properties:{taskId:{type:'string'}},required:['taskId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='taskId')||typeof input.taskId!=='string'||!data.tasks.some(t=>t.id===input.taskId))throw new Error('Unknown task.');M.mutate('task',{id:input.taskId,done:true},role);return {taskId:input.taskId,done:true};}}];for(const definition of definitions){try{Promise.resolve(document.modelContext.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
})();
